228	    private Xpb98Status mapToShipmentStatus(String statusText) {
229	        return switch (statusText) {
230	            case "배송완료" -> Xpb98Status.DELIVERED;
231	            case "배송출발" -> Xpb98Status.OUT_FOR_DELIVERY;
232	            default -> Xpb98Status.IN_TRANSIT;
233	        };
234	    }
