318	public class Xth19Processor implements ItemProcessor<Xhx14, Xhx14> {
319	
320	    private final Xrk74 browserManager;
321	    private final Xkh73CommandService notificationService;
322	    private final Xhx14CommandService orderService;
323	
324	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
325	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
326	    private static final int TIMEOUT_MS = 30000;
327	
