335	    public Xth19Processor(
336	            Xrk74 browserManager,
337	            Xkh73CommandService notificationService,
338	            Xhx14CommandService orderService
339	    ) {
340	        this.browserManager = browserManager;
341	        this.notificationService = notificationService;
342	        this.orderService = orderService;
343	    }
